(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const call = async (b) => {
    try {
      const r = await fetch('/draco-ms/mms/template/property/value/search', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify(b) });
      const j = await r.json();
      const arr = j && Array.isArray(j.result) ? j.result : null;
      return { ok: !!(j && j.success), code: j && j.error_code, n: arr ? arr.length : null, first: arr && arr[0] ? arr[0].vid : null, last: arr && arr.length ? arr[arr.length - 1].vid : null, names: arr ? arr.slice(0, 3).map(x => x.value) : null };
    } catch (e) { return { err: 1 }; }
  };
  const base = { cat_id: 5908, pid: 5, template_pid: 642609 };
  const out = { kwParam: [], cap: {} };
  // 1) 暴力找关键词参数名（用 page_size=20 提速）
  const cands = ['keyword', 'key', 'kw', 'q', 'query', 'search', 'search_key', 'searchKey', 'value', 'name', 'brand_name', 'brandName', 'filter', 'text', 'term', 'match', 'prefix', 'input', 'word', 'content', 'title'];
  for (const c of cands) {
    const b = Object.assign({}, base, { page_size: 20, page_num: 1 }); b[c] = '\u5c3c\u5eb7';
    const r = await call(b);
    if (r.names && r.names.length && String(r.names[0]).indexOf('\u5c3c\u5eb7') >= 0) out.kwParam.push({ param: c, names: r.names });
    await sleep(120);
  }
  // 2) 记录上限判定：不同 page_size 下的最大可达记录数
  for (const ps of [250, 500]) {
    const last = await call(Object.assign({}, base, { page_size: ps, page_num: Math.floor(50000 / ps) }));
    const over = await call(Object.assign({}, base, { page_size: ps, page_num: Math.floor(50000 / ps) + 1 }));
    out.cap['ps' + ps] = { lastOk: last.ok, lastN: last.n, lastLastVid: last.last, overOk: over.ok, overCode: over.code, overMsg: over.msg || null };
    await sleep(200);
  }
  return JSON.stringify(out).slice(0, 3000);
})()
